package com.xa.mass.kernel.pacer;

import com.xa.mass.kernel.pacer.KernelPacerRuntime.PolicyPreset;
import com.xa.mass.kernel.score.WorkerScoreCore;
import java.util.Objects;
import java.util.function.LongSupplier;

/**
 * Root policy facts shared by both convergence packages.
 *
 * <p>Each package owns its concrete preset values. The root owns only the
 * selected finite preset and the single HOT eligibility floor shared by
 * Serviceability Dispatch and Assignment.</p>
 */
record KernelPacerPolicyConfig(
        PolicyPreset preset,
        long hotEligibilityFloorMillis
) {

    KernelPacerPolicyConfig {
        Objects.requireNonNull(preset, "preset");
        if (serviceabilityEnabled(preset)) {
            requireFloor(hotEligibilityFloorMillis);
        } else if (hotEligibilityFloorMillis != 0) {
            throw new IllegalArgumentException(
                    "disabled Serviceability must not carry a HOT floor"
            );
        }
    }

    static KernelPacerPolicyConfig forPreset(PolicyPreset preset) {
        return forPreset(preset, System::currentTimeMillis);
    }

    static KernelPacerPolicyConfig forPreset(
            PolicyPreset preset,
            LongSupplier currentTimeMillis
    ) {
        Objects.requireNonNull(preset, "preset");
        Objects.requireNonNull(currentTimeMillis, "currentTimeMillis");
        if (!serviceabilityEnabled(preset)) {
            return new KernelPacerPolicyConfig(preset, 0);
        }
        long current = currentTimeMillis.getAsLong();
        long floor = current / WorkerScoreCore.SLOT_MILLIS
                * WorkerScoreCore.SLOT_MILLIS;
        return new KernelPacerPolicyConfig(preset, floor);
    }

    boolean serviceabilityEnabled() {
        return serviceabilityEnabled(preset);
    }

    private static boolean serviceabilityEnabled(PolicyPreset preset) {
        return preset != PolicyPreset.DEFAULT;
    }

    private static void requireFloor(long floor) {
        if (floor < WorkerScoreCore.SLOT_MILLIS
                || floor % WorkerScoreCore.SLOT_MILLIS != 0
                || floor > WorkerScoreCore.MAX_TIME_MILLIS) {
            throw new IllegalArgumentException(
                    "hotEligibilityFloorMillis must be a valid "
                            + "score-slot-aligned time"
            );
        }
    }
}

package com.xa.mass.kernel.pacer.dispatch;

record AssignmentDispatchConfig(
        long workerAllocationIntervalMillis,
        long taskInitializationIntervalMillis,
        long taskDispatchIntervalMillis
) {
    static final long DEFAULT_INTERVAL_MILLIS = 100;

    AssignmentDispatchConfig {
        if (workerAllocationIntervalMillis <= 0
                || taskInitializationIntervalMillis <= 0
                || taskDispatchIntervalMillis <= 0) {
            throw new IllegalArgumentException(
                    "Assignment Dispatch intervals must be positive"
            );
        }
    }

    static AssignmentDispatchConfig defaults() {
        return create(
                DEFAULT_INTERVAL_MILLIS,
                DEFAULT_INTERVAL_MILLIS,
                DEFAULT_INTERVAL_MILLIS
        );
    }

    static AssignmentDispatchConfig create(
            long workerAllocationIntervalMillis,
            long taskInitializationIntervalMillis,
            long taskDispatchIntervalMillis
    ) {
        return new AssignmentDispatchConfig(
                workerAllocationIntervalMillis,
                taskInitializationIntervalMillis,
                taskDispatchIntervalMillis
        );
    }
}

package com.xa.mass.kernel.pacer.dispatch;

import com.xa.mass.kernel.assignment.CandidateWorkerCache;
import com.xa.mass.kernel.assignment.WorkerMatchQueue;
import com.xa.mass.kernel.delivery.ResultContextCodec;
import com.xa.mass.kernel.delivery.WorkerCommandRuntime;
import com.xa.mass.kernel.pacer.KernelPacerRuntime.PolicyPreset;
import com.xa.mass.kernel.score.TaskItemScoreBandCore;
import com.xa.mass.kernel.score.TaskScoreBandCore;
import com.xa.mass.kernel.score.WorkerScoreCore;
import com.xa.mass.kernel.serviceability.WorkerServiceabilityRuntime;
import com.xa.mass.kernel.task.TaskResourceCatalog;
import com.xa.mass.kernel.task.TaskRuntime;
import com.xa.mass.kernel.worker.WorkerResourceCatalog;
import java.util.Objects;

/**
 * Module-internal lifecycle bridge for the Dispatch Convergence package.
 *
 * <p>This type is public only so the parent package can assemble the fixed
 * runtime. Consumers outside {@code kernel_pacer_jvm} must use
 * {@code KernelPacerRuntime}.</p>
 */
public final class DispatchConvergenceRuntime {

    private static final long LAB_INTERVAL_MILLIS = 20;
    private static final long BOUNDARY_PROBE_RETRY_MILLIS = 10;

    private final DispatchMainScheduler mainScheduler;
    private Thread schedulerThread;

    DispatchConvergenceRuntime(DispatchMainScheduler mainScheduler) {
        this.mainScheduler = Objects.requireNonNull(
                mainScheduler,
                "mainScheduler"
        );
    }

    public static DispatchConvergenceRuntime assemble(
            PolicyPreset preset,
            long hotEligibilityFloorMillis,
            TaskScoreBandCore taskScores,
            TaskItemScoreBandCore itemScores,
            TaskResourceCatalog taskCatalog,
            CandidateWorkerCache candidateCache,
            WorkerScoreCore workerScores,
            WorkerResourceCatalog workerCatalog,
            TaskRuntime taskRuntime,
            WorkerCommandRuntime workerCommands,
            WorkerServiceabilityRuntime serviceability,
            WorkerMatchQueue workerMatchQueue,
            ResultContextCodec resultContextCodec
    ) {
        Objects.requireNonNull(preset, "preset");
        Objects.requireNonNull(
                resultContextCodec,
                "resultContextCodec"
        );

        AssignmentDispatchConfig assignment = assignmentConfigForPreset(
                preset
        );
        WorkerServiceabilityDispatchConfig serviceabilityConfig =
                serviceabilityConfigForPreset(
                        preset,
                        hotEligibilityFloorMillis
                );
        Long assignmentHotFloor = serviceabilityConfig == null
                ? null
                : serviceabilityConfig.hotEligibilityFloorMillis();
        TaskWorkerAllocationPolicy allocation =
                new TaskWorkerAllocationPolicy(
                        workerScores,
                        candidateCache,
                        workerMatchQueue,
                        assignmentHotFloor
                );
        WorkerCandidateSelectionPolicy candidateSelection =
                new WorkerCandidateSelectionPolicy(
                        workerScores,
                        candidateCache,
                        workerCatalog,
                        assignmentHotFloor
                );
        TaskInitializationPolicy initialization =
                new TaskInitializationPolicy(
                        itemScores,
                        taskScores
                );
        TaskAssignmentDispatcher assignmentDispatcher =
                new TaskAssignmentDispatcher(
                        itemScores,
                        workerScores,
                        workerCommands,
                        resultContextCodec
                );
        TaskIdleSettlement idleSettlement = new TaskIdleSettlement(
                taskScores,
                itemScores
        );
        TaskDispatchPolicy dispatch = new TaskDispatchPolicy(
                taskScores,
                itemScores,
                taskRuntime,
                assignmentDispatcher,
                idleSettlement,
                candidateSelection
        );
        WorkerServiceabilityDispatchPolicy serviceabilityDispatch =
                serviceabilityConfig == null
                        ? null
                        : new WorkerServiceabilityDispatchPolicy(
                                workerScores,
                                workerCatalog,
                                Objects.requireNonNull(
                                        serviceability,
                                        "serviceability"
                                )
                        );
        DispatchMainScheduler scheduler = new DispatchMainScheduler(
                taskScores,
                taskCatalog,
                initialization,
                allocation,
                dispatch,
                serviceabilityDispatch,
                assignment,
                serviceabilityConfig
        );
        return new DispatchConvergenceRuntime(scheduler);
    }

    public synchronized void start() {
        if (schedulerThread != null) {
            throw new IllegalStateException(
                    "Dispatch Convergence is already started"
            );
        }
        Thread started = Thread.ofPlatform()
                .name("dispatch-main-scheduler")
                .daemon(false)
                .unstarted(mainScheduler::run);
        schedulerThread = started;
        try {
            started.start();
        } catch (RuntimeException | Error failure) {
            schedulerThread = null;
            throw failure;
        }
    }

    public void stop(long timeoutMillis) {
        if (timeoutMillis < 1) {
            throw new IllegalArgumentException(
                    "timeoutMillis must be positive"
            );
        }
        Thread current;
        synchronized (this) {
            current = schedulerThread;
            if (current == null) {
                return;
            }
            current.interrupt();
        }
        try {
            current.join(timeoutMillis);
        } catch (InterruptedException interrupted) {
            Thread.currentThread().interrupt();
            throw new IllegalStateException(
                    "Dispatch Convergence shutdown was interrupted",
                    interrupted
            );
        }
        if (current.isAlive()) {
            throw new IllegalStateException(
                    "Dispatch Main Scheduler did not stop within its budget"
            );
        }
        synchronized (this) {
            if (schedulerThread == current) {
                schedulerThread = null;
            }
        }
    }

    public synchronized boolean isRunning() {
        return schedulerThread != null && schedulerThread.isAlive();
    }

    public synchronized String state() {
        if (schedulerThread == null) {
            return "STOPPED";
        }
        return schedulerThread.isAlive() ? "RUNNING" : "FAILED";
    }

    static AssignmentDispatchConfig assignmentConfigForPreset(
            PolicyPreset preset
    ) {
        return switch (Objects.requireNonNull(preset, "preset")) {
            case SCENARIO_LAB -> AssignmentDispatchConfig.create(
                    LAB_INTERVAL_MILLIS,
                    LAB_INTERVAL_MILLIS,
                    LAB_INTERVAL_MILLIS
            );
            case DEFAULT, SERVICEABILITY_DEFAULT,
                    RUNTIME_BOUNDARY_PROOF ->
                    AssignmentDispatchConfig.defaults();
        };
    }

    static WorkerServiceabilityDispatchConfig
            serviceabilityConfigForPreset(
                    PolicyPreset preset,
                    long hotEligibilityFloorMillis
            ) {
        return switch (Objects.requireNonNull(preset, "preset")) {
            case DEFAULT -> {
                if (hotEligibilityFloorMillis != 0) {
                    throw new IllegalArgumentException(
                            "disabled Serviceability must not carry a HOT "
                                    + "floor"
                    );
                }
                yield null;
            }
            case SERVICEABILITY_DEFAULT, SCENARIO_LAB ->
                    WorkerServiceabilityDispatchConfig.defaults(
                            hotEligibilityFloorMillis
                    );
            case RUNTIME_BOUNDARY_PROOF ->
                    new WorkerServiceabilityDispatchConfig(
                            WorkerServiceabilityDispatchConfig
                                    .DEFAULT_INTERVAL_MILLIS,
                            hotEligibilityFloorMillis,
                            BOUNDARY_PROBE_RETRY_MILLIS,
                            WorkerServiceabilityDispatchConfig
                                    .DEFAULT_PROBE_SWEEP_RESTART_DELAY_MILLIS,
                            WorkerServiceabilityDispatchConfig
                                    .DEFAULT_MAX_RECOVERY_ATTEMPTS,
                            WorkerServiceabilityDispatchConfig
                                    .DEFAULT_PROBE_EXCLUDED_ENDPOINT_IDS
                    );
        };
    }
}

package com.xa.mass.kernel.pacer.result;

record ResultConvergenceConfig(
        long taskResultIdleIntervalMillis,
        long networkEvidenceIdleIntervalMillis
) {

    static final int TASK_RESULT_BATCH_LIMIT = 100;
    static final int GLOBAL_MAX_CONCURRENCY = 10;
    static final int TASK_SUCCESS_TARGET_CONCURRENCY = 6;
    static final int TASK_SUCCESS_MAX_CONCURRENCY = 10;
    static final int TASK_FAILURE_TARGET_CONCURRENCY = 3;
    static final int TASK_FAILURE_MAX_CONCURRENCY = 10;
    static final int NETWORK_EVIDENCE_TARGET_CONCURRENCY = 1;
    static final int NETWORK_EVIDENCE_MAX_CONCURRENCY = 1;
    static final long DEFAULT_IDLE_INTERVAL_MILLIS = 100;

    ResultConvergenceConfig {
        if (taskResultIdleIntervalMillis < 1) {
            throw new IllegalArgumentException(
                    "taskResultIdleIntervalMillis must be positive"
            );
        }
        if (networkEvidenceIdleIntervalMillis < 1) {
            throw new IllegalArgumentException(
                    "networkEvidenceIdleIntervalMillis must be positive"
            );
        }
    }

    static ResultConvergenceConfig defaults() {
        return new ResultConvergenceConfig(
                DEFAULT_IDLE_INTERVAL_MILLIS,
                DEFAULT_IDLE_INTERVAL_MILLIS
        );
    }
}

package com.xa.mass.kernel.pacer.result;

import com.xa.mass.kernel.delivery.TaskResultRuntime;
import com.xa.mass.kernel.delivery.TaskResultRuntime.TaskResultClass;
import com.xa.mass.kernel.pacer.KernelPacerRuntime.PolicyPreset;
import com.xa.mass.kernel.serviceability.WorkerServiceabilityRuntime;
import com.xa.mass.kernel.task.TaskItemResultEvents;
import com.xa.mass.kernel.worker.WorkerExecutionResultEvents;
import com.xa.mass.kernel.worker.WorkerServiceabilityEvents;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

/**
 * Module-internal lifecycle bridge for the Result Convergence package.
 *
 * <p>This type is public only so the parent package can assemble the fixed
 * runtime. Consumers outside {@code kernel_pacer_jvm} must use
 * {@code KernelPacerRuntime}.</p>
 */
public final class ResultConvergenceRuntime {

    private static final long LAB_INTERVAL_MILLIS = 20;
    private static final int BOUNDARY_RESULT_REPORT_LIMIT = 100;

    private final ResultConvergenceApplication application;

    private ResultConvergenceRuntime(
            ResultConvergenceApplication application
    ) {
        this.application = Objects.requireNonNull(
                application,
                "application"
        );
    }

    public static ResultConvergenceRuntime assemble(
            PolicyPreset preset,
            TaskResultRuntime taskResults,
            TaskItemResultEvents taskItemEvents,
            WorkerExecutionResultEvents workerExecutionEvents,
            WorkerServiceabilityEvents workerServiceabilityEvents,
            WorkerServiceabilityRuntime serviceability
    ) {
        Objects.requireNonNull(preset, "preset");
        Objects.requireNonNull(taskResults, "taskResults");
        Objects.requireNonNull(taskItemEvents, "taskItemEvents");
        Objects.requireNonNull(
                workerExecutionEvents,
                "workerExecutionEvents"
        );
        Objects.requireNonNull(
                workerServiceabilityEvents,
                "workerServiceabilityEvents"
        );
        Objects.requireNonNull(serviceability, "serviceability");

        ResultConvergenceConfig convergence = configForPreset(preset);
        TaskResultBatchPolicy taskPolicy = new TaskResultBatchPolicy(
                taskItemEvents,
                workerExecutionEvents
        );
        List<ResultLane> lanes = new ArrayList<>();
        lanes.add(new ResultLane(
                ResultLaneId.TASK_SUCCESS,
                ResultConvergenceConfig.TASK_RESULT_BATCH_LIMIT,
                convergence.taskResultIdleIntervalMillis(),
                ResultConvergenceConfig.TASK_SUCCESS_TARGET_CONCURRENCY,
                ResultConvergenceConfig.TASK_SUCCESS_MAX_CONCURRENCY,
                limit -> taskResults.consumeTaskResults(
                        TaskResultClass.SUCCESS,
                        limit
                ),
                taskPolicy::handleSuccess
        ));
        lanes.add(new ResultLane(
                ResultLaneId.TASK_FAILURE,
                ResultConvergenceConfig.TASK_RESULT_BATCH_LIMIT,
                convergence.taskResultIdleIntervalMillis(),
                ResultConvergenceConfig.TASK_FAILURE_TARGET_CONCURRENCY,
                ResultConvergenceConfig.TASK_FAILURE_MAX_CONCURRENCY,
                limit -> taskResults.consumeTaskResults(
                        TaskResultClass.FAILURE,
                        limit
                ),
                taskPolicy::handleFailure
        ));
        WorkerServiceabilityResultConfig serviceabilityConfig =
                serviceabilityConfigForPreset(preset);
        WorkerServiceabilityResultPolicy evidencePolicy =
                new WorkerServiceabilityResultPolicy(
                        workerServiceabilityEvents,
                        serviceabilityConfig
                );
        lanes.add(new ResultLane(
                ResultLaneId.NETWORK_EVIDENCE,
                serviceabilityConfig.resultReportLimit(),
                convergence.networkEvidenceIdleIntervalMillis(),
                ResultConvergenceConfig.NETWORK_EVIDENCE_TARGET_CONCURRENCY,
                ResultConvergenceConfig.NETWORK_EVIDENCE_MAX_CONCURRENCY,
                serviceability::consumeNetworkEvidenceResults,
                evidencePolicy::handle
        ));
        return new ResultConvergenceRuntime(
                new ResultConvergenceApplication(
                        lanes,
                        ResultConvergenceConfig.GLOBAL_MAX_CONCURRENCY
                )
        );
    }

    public void start() {
        application.start();
    }

    public void stop(long timeoutMillis) {
        application.stop(timeoutMillis);
    }

    public boolean isRunning() {
        return application.isRunning();
    }

    public String state() {
        return application.state();
    }

    static ResultConvergenceConfig configForPreset(PolicyPreset preset) {
        return switch (Objects.requireNonNull(preset, "preset")) {
            case DEFAULT, SERVICEABILITY_DEFAULT ->
                    ResultConvergenceConfig.defaults();
            case SCENARIO_LAB -> new ResultConvergenceConfig(
                    LAB_INTERVAL_MILLIS,
                    ResultConvergenceConfig.DEFAULT_IDLE_INTERVAL_MILLIS
            );
            case RUNTIME_BOUNDARY_PROOF -> new ResultConvergenceConfig(
                    ResultConvergenceConfig.DEFAULT_IDLE_INTERVAL_MILLIS,
                    LAB_INTERVAL_MILLIS
            );
        };
    }

    static WorkerServiceabilityResultConfig serviceabilityConfigForPreset(
            PolicyPreset preset
    ) {
        return switch (Objects.requireNonNull(preset, "preset")) {
            case DEFAULT, SERVICEABILITY_DEFAULT, SCENARIO_LAB ->
                    WorkerServiceabilityResultConfig.defaults();
            case RUNTIME_BOUNDARY_PROOF ->
                    new WorkerServiceabilityResultConfig(
                            BOUNDARY_RESULT_REPORT_LIMIT,
                            WorkerServiceabilityResultConfig
                                    .DEFAULT_EVIDENCE_MAX_AGE_MILLIS
                    );
        };
    }

}

package com.xa.mass.kernel.pacer.result;

record WorkerServiceabilityResultConfig(
        int resultReportLimit,
        long evidenceMaxAgeMillis
) {

    public static final int DEFAULT_RESULT_REPORT_LIMIT = 10;
    public static final long DEFAULT_EVIDENCE_MAX_AGE_MILLIS = 30_000;

    public WorkerServiceabilityResultConfig {
        if (resultReportLimit < 1 || resultReportLimit > 100) {
            throw new IllegalArgumentException(
                    "resultReportLimit must be between 1 and 100"
            );
        }
        if (evidenceMaxAgeMillis < 1) {
            throw new IllegalArgumentException(
                    "evidenceMaxAgeMillis must be positive"
            );
        }
    }

    public static WorkerServiceabilityResultConfig defaults() {
        return new WorkerServiceabilityResultConfig(
                DEFAULT_RESULT_REPORT_LIMIT,
                DEFAULT_EVIDENCE_MAX_AGE_MILLIS
        );
    }
}

